def format_cell(cell, size=10):
    cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
    for p in cell.paragraphs:
        p.paragraph_format.space_before = Pt(0)
        p.paragraph_format.space_after = Pt(0)
        p.paragraph_format.line_spacing = 1.05
        p.alignment = WD_ALIGN_PARAGRAPH.LEFT
        for run in p.runs:
            run.font.name = "Times New Roman"
            run.font.size = Pt(size)
            run.bold = False

def set_cell(cell, text, size=10):
    cell.text = text
    format_cell(cell, size)

with opc.edit_docx(str(WORK)) as doc:
    main = doc.tables[1]
    for row_idx, text in fields.items():
        set_cell(main.cell(row_idx, 2), text, 9.5 if row_idx in {10, 13, 14, 15, 16, 17, 19, 21, 22, 23, 24, 26, 27, 30, 31, 32, 33, 34} else 10)
    for row in main.rows:
        row.height_rule = WD_ROW_HEIGHT_RULE.AT_LEAST
        row.height = None
    team_table = main.cell(8, 1).tables[0]
    for r, values in enumerate(team, 1):
        for c, value in enumerate(values):
            set_cell(team_table.cell(r, c), value, 8 if c == 6 else 8.5)
    cal = doc.tables[2]
    for r, values in enumerate(calendar, 1):
        for c, value in enumerate(values):
            set_cell(cal.cell(r, c), value, 10)
    for table in [doc.tables[0], main, team_table, cal]:
        for row in table.rows:
            row.height_rule = WD_ROW_HEIGHT_RULE.AT_LEAST
